import { createRequire } from "node:module";
import { writeFile } from "node:fs/promises";
import { fileURLToPath } from "node:url";
const { build } = createRequire(new URL("../proxy/package.json", import.meta.url))("esbuild");
const output = await build({
  entryPoints: [fileURLToPath(new URL("../src/lib/utils/umbrel-network.ts", import.meta.url))],
  bundle: true, minify: true, format: "iife", target: "es2022", write: false,
});
await writeFile(new URL("../proxy/src/umbrel-network.ts", import.meta.url),
  "// Generated by scripts/build-umbrel-network.mjs from the shared HTTPS socket client.\nexport default " + JSON.stringify(output.outputFiles[0].text) + ";\n");
